mapper.select:
SELECT count(*)
FROM tb_menu
WHERE menu_name = #{menuName} and parent_id = #{parentId}

SELECT menu_name
FROM tb_menu
WHERE menu_id =  #{parentId}

SELECT count(*)
FROM tb_menu
WHERE parent_id =  #{menuId}

SELECT count(*)
FROM tb_role_menu
WHERE menu_id = #{menuId}

SELECT menu_name
FROM tb_menu
WHERE parent_id = #{parentId} and menu_id <> #{menuId}

SELECT menu_name
FROM tb_menu
WHERE parent_id = #{menuId}

SELECT menu_id as menuId, menu_name as menuName, parent_id as parentId, order_num as orderNum, path as path, component as component, is_frame as isFrame, is_cache as isCache, menu_type as menuType, visible as visible, status as status, ifnull(perms,'') as perms, icon as icon, create_time as createtime FROM tb_menu
AND menu_name like concat('%', #{menuDto.menuName}, '%')
AND visible = #{menuDto.visible}
AND status = #{menuDto.status}
order by parent_id, order_num

SELECT DISTINCT t1.menu_id as menuId, t1.parent_id as parentId, t1.menu_name as menuName, t1.path as path, t1.component as component, t1.visible as visible, t1.status as status, ifnull(t1.perms,'') as perms, t1.is_frame as isFrame, t1.is_cache as isCache, t1.menu_type as menuType, t1.icon as icon, t1.order_num as orderNum, t1.create_time as createtime FROM tb_menu t1 LEFT JOIN tb_role_menu t2 on t1.menu_id = t2.menu_id LEFT JOIN tb_user_role t3 on t3.role_id = t2.role_id LEFT JOIN tb_user t4 on t4.user_id = t3.user_id WHERE t4.username = #{menuDto.username}
AND menu_name like concat('%', #{menuDto.menuName}, '%')
AND visible = #{menuDto.visible}
AND status = #{menuDto.status}
order by t1.parent_id, t1.order_num

SELECT menu_id as menuId
FROM tb_menu
WHERE parent_id = #{menuId1}
